Here is a clean Template Method implementation for sorting. The abstract base defines the skeleton and the hooks for `compare` / `swap`. Concrete algorithms implement the sorting steps.

```python
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    """Template for sorting algorithms."""

    def execute(self, arr):
        """Template method - invariant skeleton."""
        if arr is None:
            raise ValueError("array is None")
        self._do_sort(arr)          # algorithm specific
        return arr

    @abstractmethod
    def _do_sort(self, arr):
        """Subclasses implement the actual algorithm."""
        pass

    @abstractmethod
    def compare(self, a, b):
        """Return True if a should go before b."""
        pass

    def swap(self, arr, i, j):
        arr[i], arr[j] = arr[j], arr[i]


class BubbleSort(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def _do_sort(self, arr):
        n = len(arr)
        for i in range(n):
            swapped = False
            for j in range(0, n - i - 1):
                if self.compare(arr[j], arr[j + 1]):
                    self.swap(arr, j, j + 1)
                    swapped = True
            if not swapped:
                break


class SelectionSort(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def _do_sort(self, arr):
        n = len(arr)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(arr[min_idx], arr[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(arr, i, min_idx)


# --- Test ---
if __name__ == "__main__":
    data_int = [5, 2, 9, 1, 5, 6]
    data_str = ["banana", "apple", "cherry"]

    bubble = BubbleSort()
    sel = SelectionSort()

    print("BubbleSort int :", bubble.execute(data_int.copy()))
    print("SelectionSort int :", sel.execute([5, 2, 9, 1, 5, 6]))

    class StrBubbleSort(BubbleSort):
        def compare(self, a, b):
            return a > b

    class StrSelectionSort(SelectionSort):
        def compare(self, a, b):
            return a > b

    print("BubbleSort str :", StrBubbleSort().execute(data_str.copy()))
    print("SelectionSort str :", StrSelectionSort().execute(data_str.copy()))
```

`SortAlgorithm.execute` is the template method. `BubbleSort` and `SelectionSort` provide their own `_do_sort` implementations while reusing `compare` and `swap` from the base.
